import React, { useState, useEffect, useContext } from 'react';
import { Link } from 'react-router-dom';
import { Search, MapPin, Briefcase, DollarSign, Target, Calendar, Clock, AlertTriangle, ArrowRight, Filter, X, CheckCircle2, ChevronRight, Building2, Star, Sparkles, Plus, GraduationCap, XCircle } from 'lucide-react';
import { AppContext } from '../../App';
import { useJobs } from '../../hooks/useJobs';
import { useApplications } from '../../hooks/useApplications';

const JobOpenings = () => {
  const { user, userType } = useContext(AppContext);
  const { getAllJobs, getJobsForStudent, loading: jobsLoading } = useJobs();
  const { submitApplication, loading: appLoading } = useApplications();

  const [jobs, setJobs] = useState([]);
  const [filteredJobs, setFilteredJobs] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filters, setFilters] = useState({
    location: '',
    jobType: '',
    company: '',
    experience: ''
  });
  const [showApplicationModal, setShowApplicationModal] = useState(false);
  const [selectedJob, setSelectedJob] = useState(null);
  const [applicationData, setApplicationData] = useState({
    coverLetter: '',
    documents: []
  });
  const [applicationLoading, setApplicationLoading] = useState(false);
  const [applicationMessage, setApplicationMessage] = useState('');

  useEffect(() => {
    loadJobs();
  }, [userType, user]);

  useEffect(() => {
    applyFilters();
  }, [jobs, filters]);

  const loadJobs = async () => {
    try {
      setLoading(true);
      let jobsData;

      if (userType === 'student') {
        jobsData = await getJobsForStudent(user.id);
      } else if (userType === 'employer') {
        jobsData = await getAllJobs();
        jobsData = jobsData.filter(job => job.companyId === user.id);
      } else {
        jobsData = await getAllJobs();
      }

      setJobs(jobsData);
    } catch (error) {
      console.error('Failed to load jobs:', error);
    } finally {
      setLoading(false);
    }
  };

  const applyFilters = () => {
    let filtered = jobs;

    if (filters.location) {
      filtered = filtered.filter(job => 
        job.location.toLowerCase().includes(filters.location.toLowerCase())
      );
    }

    if (filters.jobType) {
      filtered = filtered.filter(job => job.jobType === filters.jobType);
    }

    if (filters.company) {
      filtered = filtered.filter(job => 
        job.company.toLowerCase().includes(filters.company.toLowerCase())
      );
    }

    if (filters.experience) {
      filtered = filtered.filter(job => 
        job.experience.toLowerCase().includes(filters.experience.toLowerCase())
      );
    }

    setFilteredJobs(filtered);
  };

  const handleFilterChange = (e) => {
    setFilters({
      ...filters,
      [e.target.name]: e.target.value
    });
  };

  const clearFilters = () => {
    setFilters({
      location: '',
      jobType: '',
      company: '',
      experience: ''
    });
  };

  const handleApplyClick = (job) => {
    setSelectedJob(job);
    setApplicationData({ coverLetter: '', documents: [] });
    setApplicationMessage('');
    setShowApplicationModal(true);
  };

  const handleApplicationSubmit = async (e) => {
    e.preventDefault();
    setApplicationLoading(true);
    setApplicationMessage('');

    try {
      await submitApplication({
        jobId: selectedJob.id,
        studentId: user.id,
        coverLetter: applicationData.coverLetter
      });

      setApplicationMessage('Ambition recorded. Success is imminent.');
      setTimeout(() => {
        setShowApplicationModal(false);
        setApplicationData({ coverLetter: '', documents: [] });
        loadJobs();
      }, 2000);
    } catch (error) {
      setApplicationMessage(error.message);
    } finally {
      setApplicationLoading(false);
    }
  };

  const getStatusBadge = (status) => {
    const statusConfig = {
      'active': { bg: 'bg-emerald-600/10', text: 'text-emerald-600', border: 'border-emerald-600/20' },
      'inactive': { bg: 'bg-charcoal-100', text: 'text-charcoal-600', border: 'border-charcoal-200' },
      'expired': { bg: 'bg-rose-600/10', text: 'text-rose-600', border: 'border-rose-600/20' }
    };

    const config = statusConfig[status] || { bg: 'bg-charcoal-100', text: 'text-charcoal-600', border: 'border-charcoal-200' };
    return (
      <span className={`px-3 py-1 rounded-full text-[10px] font-nexed font-black border tracking-widest uppercase ${config.bg} ${config.text} ${config.border}`}>
        {status}
      </span>
    );
  };

  const isDeadlineApproaching = (deadline) => {
    const deadlineDate = new Date(deadline);
    const now = new Date();
    const diffTime = deadlineDate - now;
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    return diffDays <= 3 && diffDays > 0;
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-onyx-900 flex items-center justify-center">
        <div className="w-12 h-12 border-4 border-gold-500/20 border-t-gold-500 rounded-full animate-spin"></div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-onyx-900 pb-24 font-sans text-pearl-200">
      {/* Cinematic Header */}
      <div className="h-72 bg-onyx-950 relative overflow-hidden">
        <div className="absolute inset-0 bg-gold-gradient opacity-[0.03]"></div>
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[1200px] h-[1200px] bg-gold-500/5 rounded-full blur-[180px]"></div>

        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-full flex flex-col justify-center relative z-10">
          <div className="flex flex-col md:flex-row md:items-end justify-between gap-8">
            <div>
              <h1 className="text-5xl md:text-7xl font-serif font-bold text-white tracking-tight leading-none mb-4">
                Strategic Openings
              </h1>
              <p className="text-pearl-500 text-xl font-light tracking-wide italic">Curating exceptional opportunities for the professional elite.</p>
            </div>
            <div className="flex items-center gap-4">
               <div className="glass px-8 py-4 rounded-2xl border border-pearl-900/10 text-gold-500 font-bold flex items-center gap-4">
                 <Sparkles size={24} className="animate-pulse" />
                 <div className="flex flex-col">
                    <span className="text-2xl leading-none">{filteredJobs.length}</span>
                    <span className="text-[10px] uppercase tracking-widest text-pearl-600">Active Roles</span>
                 </div>
               </div>
            </div>
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 -mt-16 relative z-20">

        {/* Refined Filters Bar */}
        <div className="glass rounded-[3rem] border border-pearl-900/10 p-4 mb-12 shadow-2xl flex flex-wrap lg:flex-nowrap gap-4 items-center">
          <div className="relative flex-1 min-w-[200px]">
            <Search className="absolute left-6 top-1/2 -translate-y-1/2 text-pearl-700" size={18} />
            <input 
              type="text" 
              name="company"
              placeholder="Search institutions..."
              value={filters.company}
              onChange={handleFilterChange}
              className="w-full bg-onyx-800/50 border border-pearl-900/10 rounded-2xl py-4 pl-14 pr-6 text-white outline-none focus:border-gold-500/50 transition-all font-light text-sm"
            />
          </div>
          <div className="relative flex-1 min-w-[200px]">
            <MapPin className="absolute left-6 top-1/2 -translate-y-1/2 text-pearl-700" size={18} />
            <input 
              type="text" 
              name="location"
              placeholder="Global locations..."
              value={filters.location}
              onChange={handleFilterChange}
              className="w-full bg-onyx-800/50 border border-pearl-900/10 rounded-2xl py-4 pl-14 pr-6 text-white outline-none focus:border-gold-500/50 transition-all font-light text-sm"
            />
          </div>
          <div className="relative flex-1 min-w-[200px]">
            <Briefcase className="absolute left-6 top-1/2 -translate-y-1/2 text-pearl-700" size={18} />
            <select
              name="jobType"
              value={filters.jobType}
              onChange={handleFilterChange}
              className="w-full bg-onyx-800/50 border border-pearl-900/10 rounded-2xl py-4 pl-14 pr-6 text-white outline-none focus:border-gold-500/50 transition-all font-light text-sm appearance-none cursor-pointer"
            >
              <option value="">Engagement Type</option>
              <option value="Full-time">Full-time Executive</option>
              <option value="Part-time">Part-time Strategic</option>
              <option value="Internship">Elite Residency</option>
              <option value="Contract">Strategic Consulting</option>
            </select>
          </div>
          <button 
            onClick={clearFilters}
            className="px-8 py-4 rounded-2xl border border-pearl-900/10 text-pearl-500 font-bold text-xs uppercase tracking-[0.2em] hover:bg-white/5 transition-all"
          >
            Reset
          </button>
        </div>

        {/* Job Listings Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
          {filteredJobs.length > 0 ? (
            filteredJobs.map(job => (
              <div key={job.id} className="group relative">
                <div className="absolute inset-0 bg-gold-gradient rounded-[2.5rem] opacity-0 group-hover:opacity-[0.03] transition-opacity duration-500"></div>
                <div className="glass rounded-[2.5rem] border border-pearl-900/10 h-full flex flex-col overflow-hidden shadow-xl group-hover:border-gold-500/30 transition-all duration-500 group-hover:-translate-y-2">

                  {/* Card Header */}
                  <div className="p-8 pb-0 flex justify-between items-start">
                    <div className="w-14 h-14 rounded-2xl bg-white/5 border border-pearl-900/10 flex items-center justify-center group-hover:border-gold-500/30 transition-all overflow-hidden shrink-0">
                       <img src={`https://api.dicebear.com/7.x/initials/svg?seed=${job.company}`} alt="avatar" className="w-full h-full object-cover grayscale opacity-50 group-hover:grayscale-0 group-hover:opacity-100 transition-all duration-500" />
                    </div>
                    {getStatusBadge(job.status)}
                  </div>

                  {/* Card Body */}
                  <div className="p-8 flex-1">
                    <p className="text-[10px] font-black text-pearl-700 uppercase tracking-[0.3em] mb-3">{job.company}</p>
                    <h3 className="text-2xl font-serif font-bold text-white mb-6 group-hover:text-gold-400 transition-colors">
                      <Link to={`/job/${job.id}`}>{job.title}</Link>
                    </h3>

                    <div className="space-y-4 mb-8">
                      <div className="flex items-center gap-3 text-pearl-400 text-sm font-light">
                         <MapPin size={16} className="text-gold-500/30" />
                         <span>{job.location}</span>
                      </div>
                      <div className="flex items-center gap-3 text-pearl-400 text-sm font-light">
                         <Briefcase size={16} className="text-gold-500/30" />
                         <span>{job.jobType}</span>
                      </div>
                      <div className="flex items-center gap-3 text-pearl-400 text-sm font-light">
                         <DollarSign size={16} className="text-gold-500/30" />
                         <span className="font-medium text-pearl-200 uppercase tracking-tighter">{job.salary}</span>
                      </div>
                    </div>

                    <p className="text-pearl-500 text-sm font-light leading-relaxed mb-8 line-clamp-3 italic">
                      "{job.description}"
                    </p>

                    {job.skills && (
                      <div className="flex flex-wrap gap-2 mb-8">
                        {job.skills.slice(0, 3).map(skill => (
                          <span key={skill} className="px-3 py-1 bg-white/5 rounded-lg text-[10px] font-bold text-pearl-400 border border-pearl-900/10 group-hover:border-gold-500/20 transition-all uppercase tracking-widest">
                            {skill}
                          </span>
                        ))}
                        {job.skills.length > 3 && (
                          <span className="text-[10px] font-bold text-pearl-700 uppercase tracking-widest pt-1.5 pl-1">+{job.skills.length - 3}</span>
                        )}
                      </div>
                    )}

                    {isDeadlineApproaching(job.applicationDeadline) && (
                      <div className="bg-rose-500/5 border border-rose-500/10 rounded-2xl p-4 mb-8 flex items-center gap-3">
                         <AlertTriangle size={16} className="text-rose-400" />
                         <span className="text-[10px] font-bold text-rose-400 uppercase tracking-widest">Closing Soon: {new Date(job.applicationDeadline).toLocaleDateString()}</span>
                      </div>
                    )}
                  </div>

                  {/* Card Footer */}
                  <div className="p-8 pt-0 border-t border-pearl-900/5 bg-white/[0.01]">
                    <div className="flex items-center justify-between mb-6 pt-6">
                       <div className="flex items-center gap-2">
                          <Calendar size={14} className="text-pearl-800" />
                          <span className="text-[10px] font-black text-pearl-700 uppercase tracking-widest">{new Date(job.postedDate).toLocaleDateString()}</span>
                       </div>
                       <div className="flex items-center gap-2">
                          <Star size={14} className="text-gold-500/30" />
                          <span className="text-[10px] font-black text-pearl-700 uppercase tracking-widest">{job.applicationsReceived} Aspirants</span>
                       </div>
                    </div>

                    <div className="flex gap-3">
                      <Link 
                        to={`/job/${job.id}`} 
                        className="flex-1 px-4 py-3.5 rounded-xl border border-pearl-900/10 text-pearl-400 font-bold text-[10px] uppercase tracking-[0.2em] hover:bg-white/5 hover:text-white transition-all text-center flex items-center justify-center gap-2"
                      >
                        Intel <ArrowRight size={14} />
                      </Link>
                      {userType === 'student' && (
                        <button 
                          onClick={() => handleApplyClick(job)}
                          disabled={new Date() > new Date(job.applicationDeadline)}
                          className={`flex-1 px-4 py-3.5 rounded-xl font-bold text-[10px] uppercase tracking-[0.2em] transition-all shadow-gold flex items-center justify-center gap-2 ${new Date() > new Date(job.applicationDeadline) ? 'bg-pearl-900/10 text-pearl-700 cursor-not-allowed shadow-none' : 'bg-gold-gradient text-onyx-900 hover:brightness-110'}`}
                        >
                          {new Date() > new Date(job.applicationDeadline) ? 'Archived' : 'Initiate Application'}
                        </button>
                      )}
                    </div>
                  </div>
                </div>
              </div>
            ))
          ) : (
            <div className="col-span-full py-32 glass rounded-[3rem] border border-pearl-900/10 text-center">
              <div className="w-24 h-24 bg-onyx-800 rounded-3xl flex items-center justify-center mx-auto mb-8 border border-pearl-900/10">
                <Target className="text-pearl-800" size={40} />
              </div>
              <h4 className="text-3xl font-serif font-bold text-white mb-3">No matching openings cataloged</h4>
              <p className="text-pearl-600 font-light italic max-w-md mx-auto">
                {userType === 'student' 
                  ? "Adjust your strategic parameters or complete your professional portfolio to unlock new horizons."
                  : "No opportunities match the current search filters."
                }
              </p>
              <button 
                onClick={clearFilters}
                className="mt-10 px-8 py-4 bg-white/5 rounded-2xl text-gold-500 font-bold uppercase tracking-[0.2em] text-xs hover:bg-white/10 transition-all border border-gold-500/10"
              >
                Reset Parameters
              </button>
            </div>
          )}
        </div>
      </div>

      {/* Application Initiation Modal */}
      {showApplicationModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-charcoal-900/60 backdrop-blur-md" onClick={() => setShowApplicationModal(false)}></div>
          <div className="bg-white w-full max-w-4xl rounded-[3rem] border border-charcoal-100 shadow-2xl relative z-10 overflow-hidden animate-zoom-in">
            <div className="p-10 md:p-14">
              <div className="flex justify-between items-start mb-12">
                <div>
                  <h3 className="text-4xl font-nexed font-bold text-charcoal-900 mb-2">Initiate Protocol</h3>
                  <p className="text-charcoal-500 text-sm font-nexed font-light italic">Establish your connection for the selected mandate.</p>
                </div>
                <button onClick={() => setShowApplicationModal(false)} className="w-12 h-12 rounded-full bg-charcoal-50 flex items-center justify-center text-charcoal-400 hover:text-charcoal-900 transition-colors">
                  <XCircle size={24} />
                </button>
              </div>

              {applicationMessage && (
                <div className={`p-6 rounded-2xl mb-10 font-nexed font-black text-[10px] uppercase tracking-widest flex items-start gap-5 ${applicationMessage.includes('Success') ? 'bg-emerald-600/10 text-emerald-600 border border-emerald-600/20' : 'bg-rose-600/10 text-rose-600 border border-rose-600/20'}`}>
                  {applicationMessage.includes('Success') ? <CheckCircle2 size={20} className="shrink-0" /> : <AlertTriangle size={20} className="shrink-0" />}
                  <p className="leading-relaxed">{applicationMessage}</p>
                </div>
              )}

              {selectedJob && (
                <div className="mb-12 p-8 bg-charcoal-50 rounded-[2rem] border border-charcoal-100">
                   <div className="flex items-center gap-6 mb-2">
                      <div className="w-16 h-16 rounded-2xl bg-white border border-charcoal-100 flex items-center justify-center text-charcoal-900 shadow-sm overflow-hidden">
                         <img src={`https://api.dicebear.com/7.x/initials/svg?seed=${selectedJob.company}`} alt="avatar" className="w-full h-full object-cover" />
                      </div>
                      <div>
                         <h4 className="text-2xl font-nexed font-bold text-charcoal-900 mb-1">{selectedJob.title}</h4>
                         <div className="flex items-center gap-4 text-charcoal-400 text-[10px] font-nexed font-black uppercase tracking-widest">
                            <span className="flex items-center gap-2"><Building2 size={12} /> {selectedJob.company}</span>
                            <span className="flex items-center gap-2"><MapPin size={12} /> {selectedJob.location}</span>
                         </div>
                      </div>
                   </div>
                </div>
              )}

              <form onSubmit={handleApplicationSubmit} className="space-y-10">
                <div>
                  <div className="flex justify-between items-end mb-4 px-1">
                    <label className="text-[10px] font-nexed font-black text-charcoal-400 uppercase tracking-[0.2em]">Strategic Intent & Vision</label>
                    <span className={`text-[10px] font-nexed font-black uppercase tracking-widest ${applicationData.coverLetter.length < 50 ? 'text-rose-600' : 'text-charcoal-400'}`}>
                      {applicationData.coverLetter.length} / 1000
                    </span>
                  </div>
                  <textarea
                    rows={8}
                    value={applicationData.coverLetter}
                    onChange={(e) => setApplicationData({ ...applicationData, coverLetter: e.target.value })}
                    placeholder="Articulate your professional unique value proposition and strategic fit for this mandate..."
                    required
                    minLength={50}
                    maxLength={1000}
                    className="w-full px-8 py-6 rounded-3xl bg-charcoal-50 border border-charcoal-100 focus:border-charcoal-900 outline-none transition-all font-nexed font-light text-charcoal-800 resize-none leading-loose text-lg"
                  />
                  <p className="text-[9px] text-charcoal-400 font-nexed font-black uppercase tracking-[0.1em] mt-3 ml-1">Minimal intensity: 50 characters required.</p>
                </div>

                <div className="pt-8 flex gap-6 justify-end">
                  <button type="button" onClick={() => setShowApplicationModal(false)} disabled={applicationLoading} className="px-10 py-4 rounded-2xl font-nexed font-black text-charcoal-400 hover:text-charcoal-900 transition-all text-[10px] uppercase tracking-[0.2em]">
                    Cancel Initiation
                  </button>
                  <button 
                    type="submit" 
                    disabled={applicationLoading || applicationData.coverLetter.length < 50}
                    className="px-12 py-4 rounded-2xl font-nexed font-black text-white bg-charcoal-gradient hover:brightness-110 disabled:opacity-30 disabled:cursor-not-allowed transition-all shadow-charcoal flex items-center gap-4 text-[10px] uppercase tracking-[0.2em]"
                  >
                    {applicationLoading ? (
                      <><div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></div> Transmitting...</>
                    ) : (
                      <>Transmit Application <Sparkles size={18} /></>
                    )}
                  </button>
                </div>
              </form>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default JobOpenings;
